:root {
  --ink: #25352e;
  --paper: #fffdf7;
  --line: #d9dfd2;
  --leaf: #37634d;
  --leaf-soft: #e3eee4;
  --sun: #f4c953;
}

.pickup-tag {
  width: 460px;
  display: flex;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.mark {
  width: 108px;
  display: grid;
  place-items: center;
  background: var(--sun);
  font-size: 38px;
}

.details {
  flex: 1;
  padding: 16px 18px;
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--leaf);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-size: 22px;
  line-height: 1.1;
}

.meta {
  margin: 6px 0 11px;
  color: var(--ink);
  font-size: 14px;
}

.status {
  display: inline-block;
  margin: 0;
  padding: 5px 9px;
  background: var(--leaf-soft);
  border-radius: 999px;
  color: var(--leaf);
  font-size: 12px;
  font-weight: 700;
}
